#!/bin/bash
function calculate_tax {
    local income=$1
    if (( income < 10000 )); then
        echo $(bc <<< "scale=2; $income * 0.1")
    elif (( income < 50000 )); then
        echo $(bc <<< "scale=2; $income * 0.2")
    elif (( income < 100000 )); then
        echo $(bc <<< "scale=2; $income * 0.3")
    else
        echo "None"
    fi
}

tax=$(calculate_tax 150000)
if [[ $tax == "None" ]]; then
    echo "No default case for income tax calculation."
fi

#!/bin/bash
function get_weekday_name {
    local day_number=$1
    case $day_number in
        1)
            echo "Monday"
            ;;
        2)
            echo "Tuesday"
            ;;
        3)
            echo "Wednesday"
            ;;
        4)
            echo "Thursday"
            ;;
        5)
            echo "Friday"
            ;;
        6)
            echo "Saturday"
            ;;
        *)
            echo "None"
            ;;
    esac
}

day_name=$(get_weekday_name 7)
